URI="mongodb://root:${MONGO_PW}@mongo-0.mongo:27017,mongo-1.mongo:27017,mongo-2.mongo:27017/fixture?replicaSet=rs0&authSource=admin&w=majority"
while true; do
  mongosh --quiet "$URI" --eval '
    let n = 0;
    while (true) {
      try { db.ticks.insertOne({ts: new Date(), r: Math.random()}); n++; }
      catch (e) { print("insert failed " + new Date().toISOString() + " " + e.message); }
      if (n % 60 === 0) print("inserted " + n + " " + new Date().toISOString());
      sleep(1000);
    }' || sleep 5
done

